contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Test interestFor: amount_, rate_, duration_
    function run(uint256 amount_, uint256 rate_, uint256 duration_) public payable {
        // bound duration to avoid overflow in multiplication and to make the mathematical relation simple
        require(duration_ <= 365 days, "duration too large");

        // call the pure function on c (view) to get result
        uint256 res = c.interestFor(amount_, rate_, duration_); if (__ESBMC_reverted()) return;

        // compute expected using same formula but avoid intermediate overflow by using checked order
        // expected = (amount_ * ((rate_ * duration_) / 365 days)) / 1e18
        uint256 numerator = rate_ * duration_;
        uint256 interest = numerator / (365 days);
        uint256 expected = (amount_ * interest) / 1e18;

        // single general assertion: returned value equals expected computed value
        assert(res == expected);
    }

    receive() external payable {}
}

